import { test, before, after } from "node:test";
import assert from "node:assert/strict";
import path from "node:path";
import { loopar } from "loopar";
import { bootTestTenant } from "../support/tenant.js";

/**
 * Gym billing on erp: a membership bills a Draft Invoice (generated by its
 * Gym Membership Period); money at the desk issues it, pays it with an erp
 * Payment counted in the cashier's Cash Shift, and the paid invoice
 * activates the membership through the onInvoiceStatus hook.
 */
let t;
let server;
let billing;
let card;
const root = process.cwd();
const gym = (...p) => path.join(root, "apps", "gym", "modules", ...p);

before(async () => {
  t = await bootTestTenant({ apps: ["erp", "fiscal", "gym"] });
  server = await import(gym("gym", "shared", "server.js"));
  billing = await import(gym("gym", "shared", "billing.js"));
  card = await import(gym("gym", "shared", "member-card.js"));
});
after(async () => { await t?.teardown(); });

// Local dates, as the app counts them (a UTC date is "tomorrow" in the evening).
const localDate = (d) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
const today = () => localDate(new Date());
let plan;
let ana;
let membership;

test("a plan bills with its own service item; enrollment has one too", async () => {
  await t.run(async () => {
    const tax = await loopar.newDocument("Tax Template", { name: "Tax 15", tax_name: "Tax 15%", rate: 15, included_in_price: 1, is_default: 1 });
    tax.__KEEP_NAME__ = true;
    await tax.save();
    const doc = await loopar.newDocument("Gym Plan", { plan_name: "Monthly Test", plan_type: "Membership", billing_period: "Monthly", price: 1150, enrollment_fee: 230, tax_template: "Tax 15", active: 1 });
    await doc.save();
    plan = doc.name;
    const row = await loopar.db.getRow("Gym Plan", plan, ["item"]);
    assert.equal(row.item, plan);
    const item = await loopar.db.getRow("Item", plan, ["item_name", "item_type", "rate", "tax_template"]);
    assert.deepEqual({ ...item }, { item_name: "Monthly Test", item_type: "Service", rate: 1150, tax_template: "Tax 15" });
    assert.equal(await billing.enrollmentItem(), "Enrollment");
    const range = await loopar.newDocument("Fiscal Range", {
      authorization: "TEST-AUTH", document_type: "Invoice", prefix: "000-001-01-", digits: 8, range_start: 1, range_end: 100, next_number: 1,
      deadline: localDate(new Date(Date.now() + 90 * 864e5)), active: 1,
    });
    await range.save();
  });
});

test("a new membership bills a Draft invoice (plan + enrollment, tax included) generated by its period", async () => {
  await t.run(async () => {
    ana = (await server.createMember({ full_name: "Ana Martinez", phone: "555-1201", email: "ana@example.com" })).name;
    const m = await loopar.newDocument("Gym Membership", { member: ana, plan, start_date: today() });
    await m.save();
    membership = m.name;

    const periods = await loopar.db.getAll("Gym Membership Period", ["name", "status", "invoice", "first_period", "amount"], { membership });
    assert.equal(periods.length, 1);
    const [p] = periods;
    assert.equal(p.status, "Pending");
    const inv = await loopar.getDocument("Invoice", p.invoice);
    assert.equal(inv.status, "Draft");
    assert.equal(inv.generator_document, "Gym Membership Period");
    assert.equal(inv.generator_name, p.name);
    assert.equal(Number(inv.total), 1380, "prices include the tax: the total is the price");
    assert.equal(Number(inv.tax_amount), 180);
    assert.equal((await inv.lines).length ?? JSON.parse(await inv.lines).length, 2);

    const member = await loopar.db.getRow("Gym Member", ana, ["status", "balance_due"]);
    assert.equal(member.status, "Pending");
    assert.equal(Number(member.balance_due), 1380);
  });
});

test("cash needs an open shift; the payment issues the invoice, counts in the shift and activates the membership", async () => {
  await t.run(async () => {
    await assert.rejects(billing.collect({ member: ana, amount: 1380, method: "Cash" }), /cash shift/i);

    const { ensurePosProfile, openShift, shiftTotals } = await import(path.join(root, "apps", "erp", "modules", "sales", "pos.js"));
    const shift = await openShift({ pos_profile: await ensurePosProfile(), opening_cash: 500 });

    const payment = await billing.collect({ member: ana, amount: 1500, method: "Cash" });
    assert.equal(payment.status, "Posted");
    assert.equal(payment.cash_shift, shift.name);
    assert.equal(Number(payment.unallocated_amount), 120, "what is left over stays as the member's advance");

    const period = (await loopar.db.getAll("Gym Membership Period", ["status", "invoice", "paid_on"], { membership }))[0];
    assert.equal(period.status, "Paid");
    const inv = await loopar.db.getRow("Invoice", period.invoice, ["status", "balance"]);
    assert.equal(inv.status, "Paid");

    const m = await loopar.db.getRow("Gym Membership", membership, ["status", "activated_on", "end_date"]);
    assert.equal(m.status, "Active");
    assert.ok(m.activated_on && m.end_date);

    const totals = await shiftTotals(shift.name);
    assert.equal(totals.received_total, 1500);
    assert.equal(totals.cash_expected, 2000);

    const c = await card.memberCard(ana);
    assert.equal(c.credit, 120);
    assert.equal(c.member.balance_due, -120);
    assert.equal(c.current.name, membership);
  });
});

test("the member's credit pays the next renewal at once", async () => {
  await t.run(async () => {
    const doc = await loopar.getDocument("Gym Membership", membership);
    const period = await doc.renewNow();
    const inv = await loopar.db.getRow("Invoice", period.invoice, ["status", "total", "balance", "paid_amount"]);
    assert.notEqual(inv.status, "Draft", "credit applied: the renewal was issued");
    assert.equal(Number(inv.paid_amount), 120);
    assert.equal(Number(inv.balance), 1030);
    const c = await card.memberCard(ana);
    assert.equal(c.credit, 0);
    assert.equal(c.member.balance_due, 1030);
  });
});

test("a payment reported from the portal waits as a Draft, then pays when confirmed", async () => {
  await t.run(async () => {
    const reported = await billing.reportPayment({ member: ana, amount: 1030, method: "Bank Transfer", reference: "TRF-1" });
    assert.equal(reported.status, "Draft");
    assert.equal((await billing.reportedPayments(ana)).length, 1);
    const posted = await billing.confirmReported(reported.name);
    assert.equal(posted.status, "Posted");
    assert.ok(!posted.cash_shift, "a transfer from the portal is not in the drawer");
    const c = await card.memberCard(ana);
    assert.equal(c.member.balance_due, 0);
    assert.equal(c.owed.length, 0);
  });
});

test("cancelling a membership cancels what it still bills", async () => {
  await t.run(async () => {
    const carlos = (await server.createMember({ full_name: "Carlos Hernandez" })).name;
    const m = await loopar.newDocument("Gym Membership", { member: carlos, plan, start_date: today() });
    await m.save();
    const doc = await loopar.getDocument("Gym Membership", m.name);
    assert.equal(await doc.cancel("Changed his mind"), 1);
    const period = (await loopar.db.getAll("Gym Membership Period", ["status", "invoice"], { membership: m.name }))[0];
    assert.equal(period.status, "Cancelled");
    assert.equal(await loopar.db.getValue("Invoice", "status", period.invoice), "Cancelled");
    assert.equal(Number(await loopar.db.getValue("Gym Member", "balance_due", carlos)), 0);
  });
});

test("the demo loads on an empty gym through the real erp flows", async () => {
  await t.run(async () => {
    for (const m of await loopar.db.getAll("Gym Member", ["name"])) await loopar.db.qx()("Gym Member").where({ name: m.name }).delete();
    const { seedDemo } = await import(gym("gym", "shared", "demo.js"));
    const result = await seedDemo();
    const skipped = result.log.filter((l) => l.startsWith("("));
    assert.deepEqual(skipped, [], skipped.join("\n"));
    assert.equal(result.members, 12);
    const dash = await import(gym("gym-desk", "pages", "gym-dashboard", "gym-dashboard-controller.js"));
    assert.ok(dash.default);
  });
});
